pragma solidity ^0.8.20;

contract OzV5PausableToken {
    struct ERC20Storage {
        mapping(address => uint256) _balances;
        mapping(address => mapping(address => uint256)) _allowances;
        uint256 _totalSupply;
    }

    bytes32 private constant ERC20StorageLocation =
        0x52c63247e1f47db19d5ce0460030c497f067ca4cebf71ba98eeadabe20bace00;

    function _getERC20Storage() private pure returns (ERC20Storage storage $) {
        assembly { $.slot := ERC20StorageLocation }
    }

    address public owner;
    bool public paused;

    constructor() { owner = msg.sender; }

    modifier whenNotPaused() { require(!paused, "paused"); _; }

    function pause() external { require(msg.sender == owner, "not owner"); paused = true; }

    function balanceOf(address account) public view returns (uint256) {
        ERC20Storage storage $ = _getERC20Storage();
        return $._balances[account];
    }

    function allowance(address o, address s) public view returns (uint256) {
        ERC20Storage storage $ = _getERC20Storage();
        return $._allowances[o][s];
    }

    function approve(address s, uint256 a) external returns (bool) {
        ERC20Storage storage $ = _getERC20Storage();
        $._allowances[msg.sender][s] = a;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external whenNotPaused returns (bool) {
        ERC20Storage storage $ = _getERC20Storage();
        require($._allowances[from][msg.sender] >= amount, "allowance");
        require($._balances[from] >= amount, "balance");
        $._allowances[from][msg.sender] -= amount;
        $._balances[from] -= amount;
        $._balances[to] += amount;
        return true;
    }
}
